async function tg(m){if(!TG_TOKEN||!TG_CHAT)return;try{await fetch(`https://api.telegram.org/bot${TG_TOKEN}/sendMessage`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id:TG_CHAT,text:m,parse_mode:'HTML'})});}catch(e){}}
const TEAMS_16=[{name:'Man Utd',short:'MUN'},{name:'Aston Villa',short:'AVL'},{name:'Crystal Palace',short:'CRY'},{name:'Everton',short:'EVE'},{name:'Tottenham',short:'TOT'},{name:'West Ham',short:'WHU'},{name:'Liverpool',short:'LIV'},{name:'Wolves',short:'WOL'},{name:'Arsenal',short:'ARS'},{name:'Chelsea',short:'CHE'},{name:'Brentford',short:'BRE'},{name:'Brighton',short:'BHA'},{name:'Man City',short:'MCI'},{name:'Fulham',short:'FUL'},{name:'Newcastle',short:'NEW'},{name:'Nottm Forest',short:'NFO'}];
function genSched(){let teams=[...TEAMS_16],rounds=[],n=teams.length,fixed=teams[0],rot=teams.slice(1);for(let r=0;r<n-1;r++){let fixtures=[],all=[fixed,...rot];for(let i=0;i<n/2;i++){let h=all[i],a=all[n-1-i];if(r%2===0)fixtures.push({home:h,away:a});else fixtures.push({home:a,away:h});}rot=[rot[rot.length-1],...rot.slice(0,rot.length-1)];rounds.push(fixtures);}return rounds;}
let seasonSchedule=genSched(),season=1,matchday=0;
function getFix(md){return seasonSchedule[md%15].map((m,i)=>({...m,id:(md+1)*100000+i*1000+Math.floor(Math.random()*900)}));}
let currentFixtures=getFix(matchday),nextFixtures=getFix(matchday+1),liveFixtures=null,targetScores=null,virtualPhase='betting',virtualTimeLeft=120,pastResults=[],leagueTable={};
function initTable(){leagueTable={};TEAMS_16.forEach(t=>{leagueTable[t.short]={name:t.name,short:t.short,pld:0,w:0,d:0,l:0,gf:0,ga:0,pts:0};});}initTable();
function updateTable(fix){fix.forEach(f=>{let hg=parseInt(f.score.split('-')[0]),ag=parseInt(f.score.split('-')[1]);let ht=leagueTable[f.home.short],at=leagueTable[f.away.short];if(!ht||!at)return;ht.pld++;at.pld++;ht.gf+=hg;ht.ga+=ag;at.gf+=ag;at.ga+=hg;if(hg>ag){ht.w++;ht.pts+=3;at.l++;}else if(ag>hg){at.w++;at.pts+=3;ht.l++;}else{ht.d++;at.d++;ht.pts+=1;at.pts+=1;}});}
function s2r(s){let h=parseInt(s.split('-')[0]),a=parseInt(s.split('-')[1]);if(h>a)return'home';if(a>h)return'away';return'draw';}
function pickFinalScore(c){if(c==='home')return['1-0','2-0','2-1','3-1'][Math.floor(Math.random()*4)];if(c==='away')return['0-1','0-2','1-2','0-3'][Math.floor(Math.random()*4)];return['0-0','1-1','2-2'][Math.floor(Math.random()*3)];}
function decideTargets(fx){let t={};fx.forEach(f=>{let r=Math.random(),ch=r<0.40?'home':r<0.75?'away':'draw';t[f.id]=pickFinalScore(ch);});return t;}
function maybeGoal(){if(!liveFixtures||!targetScores)return;if(Math.random()>0.20)return;let c=liveFixtures.filter(f=>{let h=parseInt(f.score.split('-')[0]),a=parseInt(f.score.split('-')[1]),th=parseInt(targetScores[f.id].split('-')[0]),ta=parseInt(targetScores[f.id].split('-')[1]);return h<th||a<ta;});if(!c.length)return;let f=c[Math.floor(Math.random()*c.length)];let h=parseInt(f.score.split('-')[0]),a=parseInt(f.score.split('-')[1]),th=parseInt(targetScores[f.id].split('-')[0]),ta=parseInt(targetScores[f.id].split('-')[1]);if(h<th&&a<ta){Math.random()<0.5?h++:a++;}else if(h<th)h++;else if(a<ta)a++;f.score=h+'-'+a;f.result=s2r(f.score);}
setInterval(async()=>{virtualTimeLeft--;if(virtualPhase==='betting'&&virtualTimeLeft<=0){targetScores=decideTargets(currentFixtures);liveFixtures=currentFixtures.map(m=>({id:m.id,home:m.home,away:m.away,score:'0-0',result:'draw'}));virtualPhase='first_half';virtualTimeLeft=45;}else if(virtualPhase==='first_half'){maybeGoal();if(virtualTimeLeft<=0){virtualPhase='halftime';virtualTimeLeft=5;}}else if(virtualPhase==='halftime'&&virtualTimeLeft<=0){virtualPhase='second_half';virtualTimeLeft=45;}else if(virtualPhase==='second_half'){maybeGoal();if(virtualTimeLeft<=0){if(liveFixtures&&targetScores){liveFixtures.forEach(f=>{if(targetScores[f.id]){f.score=targetScores[f.id];f.result=s2r(f.score);}});if(db){try{let md=matchday+1;let res=await db.query("SELECT * FROM virtual_accas WHERE season=? AND matchday=? AND status='pending'",[season,md]);let accas=res[0];updateTable(liveFixtures);pastResults.unshift({matchday:md,season,fixtures:liveFixtures.map(x=>({...x})),ts:Date.now()});if(pastResults.length>20)pastResults.pop();for(let a of accas){let sels=[];try{sels=JSON.parse(a.selections);}catch(err){}let win=true;for(let s of sels){let mf=liveFixtures.find(x=>x.id==s.matchId);if(!mf||mf.result!==s.prediction){win=false;break;}}if(win){let wa=Math.floor(a.amount*a.odd);await db.query("UPDATE virtual_accas SET status='won', winAmount=? WHERE id=?",[wa,a.id]);await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[wa,a.userId]);}else await db.query("UPDATE virtual_accas SET status='lost' WHERE id=?",[a.id]);}}catch(err){}}}matchday++;if(matchday>=15){season++;matchday=0;seasonSchedule=genSched();initTable();}currentFixtures=nextFixtures;nextFixtures=getFix(matchday+1);liveFixtures=null;targetScores=null;virtualPhase='betting';virtualTimeLeft=120;}}},1000);
let crashState={phase:'betting',mult:1.00,crashPoint:2.00,timeLeft:10,history:[]};
function newCrashPoint(){let r=Math.random();if(r<0.08)return(1+Math.random()*0.2).toFixed(2);if(r<0.30)return(1.1+Math.random()*0.9).toFixed(2);return(1.5+Math.random()*8).toFixed(2);}
setInterval(()=>{if(crashState.phase==='betting'){crashState.timeLeft--;if(crashState.timeLeft<=0){crashState.phase='flying';crashState.mult=1.00;crashState.crashPoint=parseFloat(newCrashPoint());}}else if(crashState.phase==='flying'){crashState.mult=parseFloat((crashState.mult+0.04+crashState.mult*0.02).toFixed(2));if(crashState.mult>=crashState.crashPoint){crashState.phase='crashed';crashState.timeLeft=5;crashState.history.unshift(crashState.crashPoint);if(crashState.history.length>15)crashState.history.pop();}}else if(crashState.phase==='crashed'){crashState.timeLeft--;if(crashState.timeLeft<=0){crashState.phase='betting';crashState.timeLeft=10;crashState.mult=1.00;}}},200);
(async()=>{try{let u=(process.env.DATABASE_URL||process.env.MYSQL_URL||"").trim();if(!u)return;let p=new URL(u);db=mysql.createPool({host:p.hostname,user:p.username,password:decodeURIComponent(p.password),database:p.pathname.replace("/","").split("?")[0]||"defaultdb",port:p.port||19073,ssl:{rejectUnauthorized:false},waitForConnections:true,connectionLimit:10});await db.query("SELECT 1");console.log("DB OK");await db.query("CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, fullName VARCHAR(100), phone VARCHAR(30), password VARCHAR(100), withdrawPassword VARCHAR(100), myReferralCode VARCHAR(20), referredBy VARCHAR(20), balance INT DEFAULT 0, gameBalance INT DEFAULT 0)");await db.query("CREATE TABLE IF NOT EXISTS deposits (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, phone VARCHAR(30), amount INT, airtelNo VARCHAR(30), screenshot LONGTEXT, screenshotHash VARCHAR(100), status VARCHAR(20) DEFAULT 'pending', createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");await db.query("CREATE TABLE IF NOT EXISTS investments (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, club VARCHAR(50), amount INT, rate INT, lockDays INT, profitPaid INT DEFAULT 0, startDate DATETIME DEFAULT CURRENT_TIMESTAMP, status VARCHAR(20) DEFAULT 'active')");await db.query("CREATE TABLE IF NOT EXISTS virtual_accas (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, season INT, matchday INT, selections TEXT, amount INT, odd FLOAT, status VARCHAR(20) DEFAULT 'pending', winAmount INT DEFAULT 0, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");await db.query("CREATE TABLE IF NOT EXISTS withdrawals (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, phone VARCHAR(30), amount INT, status VARCHAR(20) DEFAULT 'pending', createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");await db.query("CREATE TABLE IF NOT EXISTS crash_bets (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, amount INT, cashoutAt FLOAT, crashAt FLOAT, status VARCHAR(20), win INT, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");await db.query("CREATE TABLE IF NOT EXISTS wheel_bets (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, amount INT, mult FLOAT, win INT, status VARCHAR(20), createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");await db.query("CREATE TABLE IF NOT EXISTS dice_bets (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, amount INT, roll INT, target INT, type VARCHAR(10), win INT, status VARCHAR(20), createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");console.log("FINAL V8 FIXED ARROW + 5 ODDS");tg("✅ FINAL V8 FIXED LIVE");}catch(e){console.log("DB ERR",e.message)}})();
