const wheelPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}.top{position:fixed;top:10px;left:50%;transform:translateX(-50%);background:#000;border:1px solid gold;padding:6px 16px;border-radius:20px;color:gold;font-size:11px;z-index:10}.wheelWrap{position:relative;width:310px;height:310px;margin:65px auto 12px}.wheel{width:100%;height:100%;border-radius:50%;border:8px solid gold;position:relative;background:conic-gradient(#f44 0deg 126deg, #111 126deg 216deg, #0a0 216deg 288deg, #ff8c00 288deg 331.2deg, #ffd700 331.2deg 360deg);display:flex;align-items:center;justify-content:center;box-shadow:0 0 35px rgba(255,215,0,0.6)}.center{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:74px;height:74px;background:#000;border:4px solid gold;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;z-index:6;box-shadow:0 0 15px gold}.label{position:absolute;width:70px;text-align:center;font-size:15px;font-weight:900;color:#fff;text-shadow:0 1px 5px #000,0 0 8px #000;left:50%;top:50%;transform-origin:0 0}.arrow{position:absolute;top:-24px;left:50%;transform:translateX(-50%);width:0;height:0;border-left:22px solid transparent;border-right:22px solid transparent;border-top:34px solid #FFD700;z-index:20;filter:drop-shadow(0 4px 8px rgba(0,0,0,0.9))}.rewards{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin:14px 0}.rewardBox{background:#1a1a1a;border:1px solid gold;border-radius:10px;padding:10px;text-align:center;font-size:11px;font-weight:900}.card{background:#111;border:1px solid gold;border-radius:16px;padding:14px;margin:10px 0}input,button{width:100%;padding:14px;border-radius:12px;border:none;margin:6px 0}button{background:gold;font-weight:900;color:#000;font-size:16px}input{background:#000;color:#fff;border:1px solid gold}</style></head><body><div class='top'>WHEEL • FIXED V8 • 0/1.5/2/2.5/3.0 • ALWAYS FAST</div><a href='/dashboard' style='color:gold;margin-top:40px;display:inline-block'>← Back</a><div class='wheelWrap'><div class='arrow' id='arrowEl'></div><div class='wheel' id='wheelEl' style='transform:rotate(0deg)'><span class='label' style='transform:rotate(63deg) translate(0,-125px) rotate(-63deg)'>×0</span><span class='label' style='transform:rotate(171deg) translate(0,-125px) rotate(-171deg)'>×1.5</span><span class='label' style='transform:rotate(252deg) translate(0,-125px) rotate(-252deg)'>×2.0</span><span class='label' style='transform:rotate(309.6deg) translate(0,-125px) rotate(-309.6deg)'>×2.5</span><span class='label' style='transform:rotate(345.6deg) translate(0,-125px) rotate(-345.6deg);color:#000'>×3.0</span></div><div class='center'>🎡</div></div><div class='rewards'><div class='rewardBox' style='border-color:#f44;color:#f44;background:#300'>×0<br>35% LOSE</div><div class='rewardBox'>×1.5<br>25% WIN</div><div class='rewardBox' style='border-color:#0f0;color:#0f0'>×2.0<br>20% WIN</div><div class='rewardBox' style='border-color:#ff8c00;color:#ff8c00'>×2.5<br>12% BIG</div><div class='rewardBox' style='border-color:gold;color:gold;background:#332a00'>×3.0<br>8% JACKPOT</div></div><div style='text-align:center;margin-top:8px'><b id='resText' style='font-size:42px;color:gold;text-shadow:0 0 14px gold'>-</b><div id='balText' style='font-size:13px;margin-top:4px'>Bal: Loading...</div></div><div class='card'><input id='amt' type='number' value='1000' min='500'><button onclick='spinWheel()' id='spinBtn'>🎡 SPIN WHEEL</button><div id='msgText' style='text-align:center;margin-top:12px;min-height:24px;font-weight:900'></div></div><script>let uid=localStorage.getItem('uid');let spinning=false;let currentBal=0;let currentRot=0;const SEGMENTS=[{mult:0,start:0,end:126,center:63},{mult:1.5,start:126,end:216,center:171},{mult:2.0,start:216,end:288,center:252},{mult:2.5,start:288,end:331.2,center:309.6},{mult:3.0,start:331.2,end:360,center:345.6},{mult:3,start:331.2,end:360,center:345.6}];async function loadBal(){if(!uid){balText.textContent='Not logged in';return;}try{let r=await fetch('/api/user/'+uid);let u=await r.json();currentBal=(u.balance||0)+(u.gameBalance||0);balText.textContent='Bal: '+currentBal.toLocaleString()+' UGX (WALLET '+(u.balance||0)+' + BAL '+(u.gameBalance||0)+')';}catch(e){balText.textContent='Bal error';}}async function spinWheel(){if(spinning)return;let a=parseInt(amt.value);if(a<500)return alert('Min 500');if(!uid){location.href='/';return;}if(currentBal<a){alert('No Balance! Need '+a+' have '+currentBal);return;}spinning=true;spinBtn.textContent='⚡ FAST...';spinBtn.disabled=true;msgText.innerHTML='<span style=color:#0ff>⚡ SUPER FAST...</span>';arrowEl.style.animation='pulse 0.12s infinite';let apiData=null;let apiDone=false;let apiError=null;fetch('/api/games/wheel/spin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a})}).then(r=>r.json()).then(d=>{apiData=d;apiDone=true;}).catch(e=>{apiError=e;apiDone=true;});let fastInterval=setInterval(()=>{currentRot+=80;wheelEl.style.transition='none';wheelEl.style.transform='rotate('+currentRot+'deg)';},16);setTimeout(()=>{clearInterval(fastInterval);let poll=setInterval(()=>{if(!apiDone)return;clearInterval(poll);if(apiError){resText.textContent='ERROR';msgText.textContent='Network '+apiError.message;spinning=false;spinBtn.textContent='🎡 SPIN WHEEL';spinBtn.disabled=false;arrowEl.style.animation='';return;}if(apiData.error){resText.textContent='ERROR';msgText.innerHTML='<span style=color:#f44>❌ '+apiData.error+'</span>';spinning=false;spinBtn.textContent='🎡 SPIN WHEEL';spinBtn.disabled=false;arrowEl.style.animation='';return;}let targetMult=parseFloat(apiData.mult);let seg=SEGMENTS.find(s=>Math.abs(s.mult-targetMult)<0.01)||SEGMENTS[0];let jitter=(Math.random()-0.5)*(seg.end-seg.start)*0.55;let targetCenter=seg.center+jitter;targetCenter=((targetCenter%360)+360)%360;let desiredMod=(360-targetCenter)%360;let currentMod=((currentRot%360)+360)%360;let delta=(desiredMod-currentMod+360)%360;let fullSpins=6;let finalRot=currentRot+fullSpins*360+delta;wheelEl.style.transition='transform 2.8s cubic-bezier(0.05,0,0.15,1)';wheelEl.style.transform='rotate('+finalRot+'deg)';currentRot=finalRot;msgText.innerHTML='<span style=color:gold>🎯 Braking to ×'+targetMult+'... arrow will match!</span>';setTimeout(()=>{arrowEl.style.animation='';resText.textContent='×'+targetMult;resText.style.color=targetMult===0?'#f44':'gold';if(apiData.win>0){msgText.innerHTML='<span style=color:#0f0;font-size:22px>✅ WON '+apiData.win.toLocaleString()+' @ ×'+targetMult+' - Arrow on ×'+targetMult+'</span>';}else{msgText.innerHTML='<span style=color:#f44;font-size:18px>❌ LOST ×0 - Arrow on ×0</span>';}spinning=false;spinBtn.textContent='🎡 SPIN WHEEL';spinBtn.disabled=false;loadBal();},2900);},100);},1500);}loadBal();<\/script><style>@keyframes pulse{0%{transform:translateX(-50%) scale(1)}50%{transform:translateX(-50%) scale(1.35)}100%{transform:translateX(-50%) scale(1)}}</style></body></html>";
const dicePage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}.top{position:fixed;top:10px;left:50%;transform:translateX(-50%);background:#000;border:1px solid gold;padding:6px 16px;border-radius:20px;color:gold;font-size:11px}.dice{font-size:90px;text-align:center;margin:50px 0 10px}.card{background:#111;border:1px solid gold;border-radius:16px;padding:14px;margin:8px 0}input,button,select{width:100%;padding:14px;border-radius:12px;border:none;margin:6px 0}button{background:gold;font-weight:900}input,select{background:#000;color:#fff;border:1px solid gold}</style></head><body><div class='top'>DICE • Over/Under</div><a href='/dashboard' style='color:gold;margin-top:40px;display:inline-block'>← Back</a><div class='dice'>🎲</div><div style='text-align:center'><b id='roll' style='font-size:36px;color:gold'>-</b><div id='bal'>0</div></div><div class='card'><input id='target' type='number' value='50' min='2' max='98'><select id='type'><option value='over'>Over</option><option value='under'>Under</option></select><input id='amt' type='number' value='1000' min='500'><button onclick='rollDice()'>ROLL</button><div id='msg' style='text-align:center'></div></div><script>let uid=localStorage.getItem('uid');async function load(){let r=await fetch('/api/user/'+uid);let u=await r.json();bal.textContent='Bal: '+((u.balance||0)+(u.gameBalance||0)).toLocaleString();}async function rollDice(){let a=parseInt(amt.value),t=parseInt(target.value),ty=type.value;let r=await fetch('/api/games/dice/roll',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a,target:t,type:ty})});let j=await r.json();if(j.error){msg.textContent=j.error;return;}roll.textContent=j.roll;msg.innerHTML=j.win>0?'<span style=color:#0f0>✅ WON '+j.win+'</span>':'<span style=color:#f44>❌ LOST roll '+j.roll+'</span>';load();}load();<\/script></body></html>";
const virtualPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{margin:0;padding:0;padding-bottom:140px;background:#111;color:#fff;font-family:Arial}.top{position:fixed;top:10px;left:50%;transform:translateX(-50%);z-index:20;background:rgba(0,0,0,0.85);border:1px solid gold;padding:5px 16px;border-radius:20px;color:gold;font-size:11px}.tabPill{display:flex;background:#222;border-radius:30px;padding:5px;margin:60px 12px 10px;gap:3px;overflow:auto}.tab{flex:1;min-width:50px;padding:10px;text-align:center;border-radius:20px;font-size:11px;color:#888;font-weight:900;cursor:pointer}.tab.active{background:#fff;color:#000}.match{background:#2a2a2a;margin:8px 12px;border-radius:14px;padding:12px}.match.live{background:#1e2e1e;border:1px solid #0f0}.odd{flex:1;background:#3a3a3a;border-radius:8px;padding:10px;display:flex;justify-content:space-between;cursor:pointer}.odd.sel{background:#1a3d1a;border:1px solid #0f0}.bar{position:fixed;bottom:0;left:0;right:0;background:#b2ff00;color:#000;padding:14px;display:flex;justify-content:space-between;font-weight:900;z-index:99}.sheet{position:fixed;bottom:0;left:0;right:0;background:#1e1e1e;max-height:85vh;overflow:auto;display:none;padding:14px;border-top:2px solid gold;z-index:100}.tableWrap{background:#1e1e1e;border-radius:16px;overflow:hidden;border:1px solid #333;margin:10px 12px}.tableHead{background:#2a2a2a;padding:12px;display:flex;justify-content:space-between;font-size:11px;color:#888;font-weight:900}.tableRow{display:flex;justify-content:space-between;align-items:center;padding:10px 12px;border-bottom:1px solid #222;font-size:13px}.pos{width:26px;text-align:center;color:#888}.teamName{flex:1;margin-left:10px;font-weight:700}.pts{width:34px;text-align:center;font-weight:900;color:gold}.stat{width:28px;text-align:center;color:#aaa}.gd{width:36px;text-align:center;color:#aaa}</style></head><body><div class='top'>MD <span id='topMD'>0</span> • 1.5/1.9/1.8</div><div class='tabPill'><div id='tabLive' class='tab active' onclick=\"switchTab('live')\">Live</div><div id='tabNext' class='tab' onclick=\"switchTab('next')\">Next</div><div id='tabTable' class='tab' onclick=\"switchTab('table')\">Table</div><div id='tabResults' class='tab' onclick=\"switchTab('results')\">Results</div><div id='tabBets' class='tab' onclick=\"switchTab('bets')\">My Bets</div></div><div id='liveSec'><div style='padding:0 12px;font-size:11px;display:flex;justify-content:space-between'><span id='phaseInfo'>BETTING</span><span id='timerTop' style='color:#ff6b00;font-weight:900'>02:00</span></div><div id='list'>Loading</div></div><div id='nextSec' style='display:none'><div id='nextList'></div></div><div id='tableSec' style='display:none'><div style='padding:8px 12px'><h3 style='color:gold;margin:8px 0'>🏆 League Table</h3><div class='tableWrap'><div class='tableHead'><span class='pos'>#</span><span class='teamName'>TEAM</span><span class='stat'>P</span><span class='stat'>W</span><span class='stat'>D</span><span class='stat'>L</span><span class='gd'>GD</span><span class='pts'>PTS</span></div><div id='tableBody'></div></div></div></div><div id='resultsSec' style='display:none'><div id='resList'></div></div><div id='betsSec' style='display:none'><div id='myBetsList' style='padding:12px'></div></div><div class='bar' onclick='openS()'><span>🎫 MD <span id='betMD'>0</span> <span id='oddShow'>0.00</span>x</span><span id='lc'>0 legs</span></div><div class='sheet' id='sheet'><h3 style='color:gold'>Betslip <span id='sc'>0</span> - Odd <span id='oddDetail'>0</span></h3><div id='sl'></div><input id='amt' type='number' value='500' min='500' max='5000' style='width:100%;padding:12px;background:#111;color:#fff;border:1px solid gold;border-radius:10px;margin:8px 0'><button onclick='place()' style='width:100%;padding:12px;background:gold'>Place Bet</button><button onclick='closeS()' style='width:100%;padding:10px;background:#222;color:#fff;margin-top:8px'>Close</button></div><script>let sel=[],currentBetMD=0,uid=localStorage.getItem('uid'),lastTable={},ODDS={home:1.5,draw:1.9,away:1.8};function switchTab(t){document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.getElementById('tab'+t.charAt(0).toUpperCase()+t.slice(1)).classList.add('active');liveSec.style.display=t==='live'?'block':'none';nextSec.style.display=t==='next'?'block':'none';tableSec.style.display=t==='table'?'block':'none';resultsSec.style.display=t==='results'?'block':'none';betsSec.style.display=t==='bets'?'block':'none';if(t==='table')renderTable(lastTable);if(t==='results')loadRes();if(t==='bets')loadBets();}function calcOdd(){if(!sel.length)return 0;let o=1;sel.forEach(s=>{o*=ODDS[s.prediction]||1.5;});return (o*0.90).toFixed(2);}function tog(id,hs,as,p,md){let phaseTxt=(document.getElementById('phaseInfo').textContent||'');if(!phaseTxt.includes('BETTING')){alert('BETTING CLOSED');return;}let ex=sel.findIndex(s=>s.matchId===id);if(ex!==-1){if(sel[ex].prediction===p)sel.splice(ex,1);else sel[ex].prediction=p;}else{if(sel.length>=5)return alert('Max 5');sel.push({matchId:id,homeShort:hs,awayShort:as,prediction:p,md});}currentBetMD=md;rend();}function rend(){document.querySelectorAll('.odd').forEach(b=>b.classList.remove('sel'));sel.forEach(s=>{let e=document.querySelector('[data-m=\"'+s.matchId+'\"][data-p=\"'+s.prediction+'\"]');if(e)e.classList.add('sel');});sc.textContent=sel.length;let co=calcOdd();oddShow.textContent=co;oddDetail.textContent=co;lc.textContent=sel.length+' legs';betMD.textContent=currentBetMD||topMD.textContent;sl.innerHTML=sel.map(s=>'<div style=\"background:#2a2a2a;padding:6px;margin:3px 0;display:flex;justify-content:space-between\"><span>MD'+s.md+' '+s.homeShort+'-'+s.awayShort+' '+s.prediction+'</span><span onclick=\"remSel('+s.matchId+')\" style=\"color:red\">✕</span></div>').join('')||'Tap odds';}function remSel(id){sel=sel.filter(s=>s.matchId!==id);rend();}function openS(){sheet.style.display='block';}function closeS(){sheet.style.display='none';}async function place(){if(!sel.length)return alert('Add');let a=parseInt(amt.value);if(a<500||a>5000)return alert('500-5000');let r=await fetch('/api/virtual/bet/acca',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a,selections:sel.map(s=>({matchId:s.matchId,homeTeam:s.homeShort,awayTeam:s.awayShort,prediction:s.prediction,md:s.md})),betMD:currentBetMD})});let j=await r.json();if(j.ok){alert('Placed');sel=[];rend();closeS();switchTab('bets');}else alert(j.error);}function renderTable(tbl){lastTable=tbl||{};let arr=Object.values(lastTable);arr.sort((a,b)=>{if(b.pts!==a.pts)return b.pts-a.pts;let gdA=a.gf-a.ga,gdB=b.gf-b.ga;return gdB-gdA;});let h='';arr.forEach((t,i)=>{let gd=t.gf-t.ga;let gdTxt=gd>0?'+'+gd:gd;h+='<div class=\"tableRow\"><span class=\"pos\">'+(i+1)+'</span><span class=\"teamName\">'+t.short+'</span><span class=\"stat\">'+t.pld+'</span><span class=\"stat\" style=\"color:#0f0\">'+t.w+'</span><span class=\"stat\">'+t.d+'</span><span class=\"stat\" style=\"color:#f44\">'+t.l+'</span><span class=\"gd\">'+gdTxt+'</span><span class=\"pts\">'+t.pts+'</span></div>';});tableBody.innerHTML=h||'Season starting...';}function renderLive(fix,phase,md){let h='';(fix||[]).forEach(m=>{let isLive=phase!=='betting';h+='<div class=\"'+(isLive?'match live':'match')+'\"><div style=\"display:flex;justify-content:space-between\"><span style=\"font-weight:900\">'+m.home.short+' - '+m.away.short+'</span>'+(isLive?'<span style=\"background:#0f0;color:#000;padding:4px 12px;border-radius:20px;font-weight:900\">LIVE '+m.score+'</span>':'<span style=\"background:#ffcc00;color:#000;padding:4px 10px;border-radius:20px;font-weight:900;font-size:11px\">BETTING</span>')+'</div>'+(isLive?'<div style=\"text-align:center;margin-top:8px\"><div style=\"font-size:22px;font-weight:900;color:#0f0\">'+m.score+'</div><div style=\"font-size:11px\">'+m.result.toUpperCase()+'</div></div>':'')+'<div style=\"display:flex;gap:5px;margin-top:10px;'+(isLive?'opacity:0.3;pointer-events:none':'')+'\"><div class=odd data-m=\"'+m.id+'\" data-p=\"home\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'home\\','+md+')\"><span>1</span><span>1.5</span></div><div class=odd data-m=\"'+m.id+'\" data-p=\"draw\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'draw\\','+md+')\"><span>X</span><span>1.9</span></div><div class=odd data-m=\"'+m.id+'\" data-p=\"away\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'away\\','+md+')\"><span>2</span><span>1.8</span></div></div></div>';});list.innerHTML=h||'No fixtures';rend();}function renderNext(fix){let h='';(fix||[]).forEach(m=>{h+='<div class=match><span>'+m.home.short+' - '+m.away.short+'</span></div>';});nextList.innerHTML=h;}async function loadRes(){let r=await fetch('/api/virtual/results');let d=await r.json();let h='';d.forEach(m=>{h+='<div style=\"background:#1e1e1e;margin:8px;padding:8px;border-left:4px solid gold\">S'+m.season+' MD'+m.matchday+' ';m.fixtures.forEach(f=>{h+='<div style=\"display:flex;justify-content:space-between;font-size:12px;padding:4px 0\"><span>'+f.home.short+' vs '+f.away.short+'</span><b style=\"color:#0f0\">'+f.score+'</b><span>'+f.result.toUpperCase()+'</span></div>';});h+='</div>';});resList.innerHTML=h||'No results yet';}async function loadBets(){let r=await fetch('/api/virtual/my-bets/'+uid);let d=await r.json();myBetsList.innerHTML=d.slice(0,30).map(b=>'<div style=\"background:#fff;color:#000;padding:8px;margin:6px 0;border-radius:8px;border-left:4px solid '+(b.status==='won'?'#0f0':b.status==='lost'?'#f44':'#000')+'\">MD'+b.matchday+' '+b.amount+'x'+b.odd+' '+b.status.toUpperCase()+'</div>').join('')||'No bets';}async function sync(){let r=await fetch('/api/virtual/status');let d=await r.json();topMD.textContent=d.matchday;lastTable=d.table||{};let tl=d.timeLeft;let disp=Math.floor(tl/60)+':'+String(tl%60).padStart(2,'0');if(d.phase!=='betting'){if(d.phase==='first_half')disp='00:'+(45-tl);else if(d.phase==='halftime')disp='00:0'+tl;else{let tot=45+(45-tl);disp=String(Math.floor(tot/60)).padStart(2,'0')+':'+String(tot%60).padStart(2,'0');}}timerTop.textContent=disp;phaseInfo.textContent=d.phase.toUpperCase()+' MD'+d.matchday;let fix=d.phase==='betting'?d.currentFixtures:d.allLive;renderLive(fix||[],d.phase,d.matchday);renderNext(d.nextFixtures);if(tableSec.style.display==='block')renderTable(d.table);if(currentBetMD===0)currentBetMD=d.phase==='betting'?d.matchday:d.nextMD;}sync();setInterval(sync,1000);<\/script></body></html>";
const depositPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}.top{position:fixed;top:14px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.8);border:1px solid gold;padding:6px 18px;border-radius:30px;color:gold;font-size:11px}input,button{width:100%;padding:14px;margin:8px 0;border-radius:12px;border:none}button{background:gold;font-weight:900}.glass{background:rgba(18,22,35,0.9);border:1px solid rgba(255,215,0,0.15);border-radius:16px;padding:16px}.merchantBox{background:linear-gradient(135deg,#1a1a00,#2a2a00);border:2px solid gold;border-radius:16px;padding:18px;margin:14px 0;text-align:center}.merchantCode{font-size:42px;font-weight:900;color:gold}</style></head><body><div class='top'>DEPOSIT</div><a href='/dashboard' style='color:gold;margin-top:60px;display:inline-block'>← Back</a><div class='merchantBox'><div style='font-size:11px;color:#aaa'>MERCHANT CODE</div><div class='merchantCode' id='mcode'>7184154</div><button onclick='copyCode()' style='width:auto;background:#fff;color:#000;padding:8px 16px;border-radius:20px'>COPY</button></div><div class='glass'><input id='am' type='number' placeholder='Amount'><input id='air' placeholder='Airtel No'><input type='file' id='file' accept='image/*'><div id='preview'></div><button onclick='dep()' id='b'>Submit</button><div id='msg'></div></div><script>let uid=localStorage.getItem('uid');let b64='',h='';file.addEventListener('change',e=>{let f=e.target.files[0];let r=new FileReader();r.onload=()=>{b64=r.result;h=Date.now()+'_'+f.size;preview.innerHTML='<img src=\"'+b64+'\" style=\"max-width:100%;border-radius:12px;max-height:200px\">';};r.readAsDataURL(f);});async function dep(){let a=am.value.trim(),air=document.getElementById('air').value.trim();if(!a||!air||!b64)return msg.textContent='Fill all';b.disabled=true;let res=await fetch('/api/deposit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:parseInt(a),airtelNo:air,screenshot:b64,screenshotHash:h})});let j=await res.json();msg.textContent=j.ok?'✅ Submitted!':'❌ '+(j.error||'Failed');if(j.ok)setTimeout(()=>location.href='/dashboard',1200);else b.disabled=false;}\<\/script></body></html>";
const investPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#0a0e1a;color:#fff;font-family:Arial;padding:12px;padding-bottom:90px}.top{position:fixed;top:10px;left:50%;transform:translateX(-50%);background:#000;border:1px solid gold;padding:6px 16px;border-radius:20px;color:gold;font-size:11px;z-index:10}.myBox{background:linear-gradient(135deg,#1a1a00,#2a2a00);border:2px solid gold;border-radius:16px;padding:14px;margin:50px 0 12px}.invActive{background:#111;border-left:4px solid #0f0;padding:10px;margin:6px 0;border-radius:10px;font-size:13px}.clubCard{background:rgba(255,255,255,0.08);border:1px solid rgba(255,215,0,0.2);border-radius:16px;padding:14px;margin:8px 0}.amtInput{flex:1;background:#000;border:1px solid gold;border-radius:12px;padding:12px;color:#fff}.invBtn{width:90px;background:gold;color:#000;font-weight:900;border-radius:12px;border:none;padding:12px}.inputRow{display:flex;gap:8px;margin-top:10px}</style></head><body><div class='top'>INVEST • 10% DAILY</div><a href='/dashboard' style='color:gold;margin-top:40px;display:inline-block'>← Back</a><div class='myBox'><div style='display:flex;justify-content:space-between'><b style='color:gold'>💼 MY INVESTMENTS</b><span id='totalInv' style='color:#0f0'>0 UGX</span></div><div id='myList' style='margin-top:10px'>Loading my invests...</div><div style='font-size:11px;color:#aaa;margin-top:8px'>Profit is paid daily to BALANCE. 10% per day for 10 days.</div></div><h3 style='color:gold;padding-left:4px'>💎 New Investment - 10% Daily</h3><div id='clubs'></div><script>let uid=localStorage.getItem('uid');const C=[{id:'arsenal',name:'Arsenal',rate:10,icon:'ARS',color:'#EF0107'},{id:'mancity',name:'Man City',rate:10,icon:'MCI',color:'#6CABDD'},{id:'liverpool',name:'Liverpool',rate:10,icon:'LIV',color:'#C8102E'}];clubs.innerHTML=C.map(c=>'<div class=clubCard><div style=\"display:flex;gap:12px;align-items:center\"><div style=\"width:48px;height:48px;border-radius:12px;background:'+c.color+';color:#fff;display:flex;align-items:center;justify-content:center;font-weight:900\">'+c.icon+'</div><div><b>'+c.name+'</b><div style=\"font-size:11px;color:#aaa\">'+c.rate+'% daily for 10 days</div></div></div><div class=inputRow><input id=\"amt_'+c.id+'\" class=amtInput type=number placeholder=\"Min 2000 UGX - WALLET needed\"><button class=invBtn onclick=\"investClub(\\''+c.id+'\\')\">INVEST</button></div></div>').join('');async function investClub(club){let el=document.getElementById('amt_'+club);let a=el.value.trim();if(!a||parseInt(a)<2000)return alert('Min 2000 UGX and need WALLET balance, not BALANCE. Go to Admin -> add WALLET');let r=await fetch('/api/invest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,club,amount:parseInt(a)})});let j=await r.json();if(j.ok){alert('✅ Invested '+a+' in '+club+'! Scroll up to see it in MY INVESTMENTS');loadMy();}else alert('❌ '+j.error);}async function loadMy(){let r=await fetch('/api/investments/'+uid);let data=await r.json();let total=0;data.forEach(i=>total+=i.amount);totalInv.textContent=total.toLocaleString()+' UGX Invested ('+data.length+')';if(!data.length){myList.innerHTML='<div style=color:#888>No investments yet. Invest using WALLET above.</div>';return;}myList.innerHTML=data.map(inv=>{let daily=Math.floor(inv.amount*inv.rate/100);let start=new Date(inv.startDate);let days=Math.floor((Date.now()-start)/86400000);let profit=days*daily;return '<div class=invActive><div style=\"display:flex;justify-content:space-between\"><b>'+inv.club.toUpperCase()+'</b><span style=\"color:gold\">'+inv.amount.toLocaleString()+' UGX</span></div><div style=\"display:flex;justify-content:space-between;margin-top:4px\"><span>'+inv.rate+'% daily = '+daily.toLocaleString()+'/day</span><span style=\"color:'+(inv.status==='active'?'#0f0':'#aaa')+'\">'+inv.status+'</span></div><div style=\"font-size:11px;color:#aaa;margin-top:4px\">Start: '+start.toLocaleDateString()+' • Days: '+days+' • Est. Profit: '+profit.toLocaleString()+' UGX<br>Lock: '+inv.lockDays+' days</div></div>';}).join('');}loadMy();<\/script></body></html>";
const withdrawPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}input,button{width:100%;padding:14px;margin:8px 0;border-radius:12px;border:none}button{background:gold;font-weight:bold}.card{background:rgba(18,22,35,0.9);padding:16px;border-radius:16px;border:1px solid #0f0}</style></head><body><a href='/dashboard' style='color:gold'>← Back</a><h2>Withdraw</h2><div class='card'><div id='bal' style='font-size:28px;color:#0f0;font-weight:900'>0</div><input id='am' type='number' placeholder='Min 5000'><input id='ph' placeholder='Airtel number'><input id='wpw' type='password' placeholder='Withdraw Password'><button onclick='wd()'>Withdraw</button><div id='msg'></div></div><div id='wlist'></div><script>let uid=localStorage.getItem('uid');async function load(){let r=await fetch('/api/user/'+uid);let u=await r.json();bal.textContent=(u.gameBalance||0).toLocaleString()+' UGX';let r2=await fetch('/api/withdrawals/'+uid);let d=await r2.json();wlist.innerHTML=d.map(x=>'<div style=\"background:#1a1a1a;padding:8px;margin:4px 0\">'+x.amount+' to '+x.phone+' '+x.status+'</div>').join('');}async function wd(){let a=parseInt(am.value),ph=document.getElementById('ph').value,wpw=document.getElementById('wpw').value;if(a<5000)return msg.textContent='Min 5k';let r=await fetch('/api/withdraw',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a,phone:ph,withdrawPassword:wpw})});let j=await r.json();msg.textContent=j.ok?'Sent':'❌ '+j.error;load();}load();<\/script></body></html>";
const historyPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}</style></head><body><div style='margin-top:20px'><a href='/dashboard' style='color:gold'>← Back</a><div id='list'></div></div><script>let uid=localStorage.getItem('uid');fetch('/api/history/'+uid).then(r=>r.json()).then(d=>{list.innerHTML=d.map(x=>'<div style=\"background:#1a1a1a;padding:8px;margin:4px 0\">'+x.type+' '+x.amount+' '+x.status+'</div>').join('')||'No data';});<\/script></body></html>";
const referralPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}.card{background:#fff;color:#000;padding:16px;border-radius:16px;margin:10px 0;border:2px solid gold}.refLink{width:100%;padding:12px;border-radius:10px;border:1px solid #ddd;font-size:12px}.teamItem{background:#1a1a1a;padding:10px;margin:6px 0;border-radius:10px;border-left:4px solid gold}</style></head><body><a href='/dashboard' style='color:gold'>← Back</a><h2 style='color:gold'>My Team</h2><div class='card'><div id='code' style='font-size:28px;font-weight:900;color:#2f6bff'>---</div><input id='refLink' class='refLink' readonly><button onclick='copyRef()' style='background:#000;color:#fff'>COPY</button></div><h3>Team (<span id='cnt'>0</span>)</h3><div id='team'>Loading</div><script>let uid=localStorage.getItem('uid');async function load(){let r=await fetch('/api/user/'+uid);let u=await r.json();code.textContent=u.myReferralCode;refLink.value=location.origin+'/?ref='+u.myReferralCode;let r2=await fetch('/api/team/'+uid);let j=await r2.json();cnt.textContent=j.team.length;team.innerHTML=j.team.map(x=>'<div class=teamItem>'+x.fullName+' - '+x.phone+'</div>').join('')||'No team';}load();<\/script></body></html>";
const adminPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Admin</title><style>body{background:#000;color:#fff;padding:12px;font-family:Arial}input,button{width:100%;padding:8px;margin:4px 0;border-radius:8px;border:none}button{background:gold;font-weight:bold}.card{background:#111;padding:10px;margin:8px 0;border-radius:10px;border-left:4px solid gold}.t{flex:1;min-width:60px;padding:10px;background:#222;border-radius:20px;text-align:center;cursor:pointer;font-size:11px}.t.active{background:#fff;color:#000}.tabs{display:flex;gap:4px;flex-wrap:wrap}.small{font-size:11px;color:#aaa;margin:2px 0}.pw{color:gold;font-size:12px;word-break:break-all}.row{display:flex;gap:4px}</style></head><body><div id='loginBox'><h2>Admin</h2><input id='pass' type='password' placeholder='LIFELINE123'><button onclick='check()'>Unlock</button></div><div id='adminBox' style='display:none'><h3>Admin Panel - V8 FIXED ARROW</h3><div class='tabs'><div id='tbDep' class='t active' onclick=\"showTab('dep')\">Deposits</div><div id='tbWith' class='t' onclick=\"showTab('with')\">Withdraws</div><div id='tbUsers' class='t' onclick=\"showTab('users')\">Users</div><div id='tbBets' class='t' onclick=\"showTab('bets')\">Bets</div></div><div id='secDep'><div id='depAdmin'></div></div><div id='secWith' style='display:none'><div id='withAdmin'></div></div><div id='secUsers' style='display:none'><input id='search' placeholder='Search phone or name' oninput='filterU()' style='background:#222;color:#fff'><div id='usersAdmin'></div></div><div id='secBets' style='display:none'><div id='l'></div><div id='crashAdmin'></div><div id='wheelAdmin'></div></div></div><script>const AP='LIFELINE123';let en='',allUsers=[];function check(){if(pass.value===AP){en=pass.value;loginBox.style.display='none';adminBox.style.display='block';loadAll();loadUsers();}}function showTab(t){document.querySelectorAll('.t').forEach(x=>x.classList.remove('active'));document.getElementById('tb'+t.charAt(0).toUpperCase()+t.slice(1)).classList.add('active');secDep.style.display=t==='dep'?'block':'none';secWith.style.display=t==='with'?'block':'none';secUsers.style.display=t==='users'?'block':'none';secBets.style.display=t==='bets'?'block':'none';}async function loadAll(){let r=await fetch('/api/admin/virtual?key='+en);let d=await r.json();l.innerHTML=(d.accas||[]).slice(0,20).map(a=>'<div class=card>MD'+a.matchday+' '+a.phone+' '+a.amount+'x'+a.odd+' '+a.status+'</div>').join('');let r2=await fetch('/api/admin/deposits?key='+en);let d2=await r2.json();depAdmin.innerHTML=d2.map(x=>'<div class=card><b>'+x.phone+' '+x.amount+'</b><br><img src=\"'+x.screenshot+'\" style=\"max-height:100px\"/><br><button onclick=\"approveDep('+x.id+','+x.userId+','+x.amount+')\" style=\"background:#0f0\">Approve</button></div>').join('')||'No deposits';let r3=await fetch('/api/admin/withdrawals?key='+en);let d3=await r3.json();withAdmin.innerHTML=d3.map(x=>'<div class=card>'+x.phone+' '+x.amount+'<br><button onclick=\"approveWith('+x.id+')\" style=\"background:#0f0\">Approve</button><button onclick=\"rejectWith('+x.id+')\" style=\"background:#f44\">Refund</button></div>').join('');let r4=await fetch('/api/admin/games?key='+en);let d4=await r4.json();crashAdmin.innerHTML='<h4>Crash</h4>'+d4.crash.map(c=>'<div class=card>U'+c.userId+' '+c.amount+' win '+c.win+'</div>').join('');wheelAdmin.innerHTML='<h4>Wheel/Dice</h4>'+d4.wheel.map(c=>'<div class=card>W U'+c.userId+' '+c.amount+' '+c.mult+'x '+c.win+'</div>').join('')+d4.dice.map(c=>'<div class=card>D U'+c.userId+' '+c.amount+' roll '+c.roll+' '+c.win+'</div>').join('');}async function loadUsers(){let r=await fetch('/api/admin/users?key='+en);let d=await r.json();allUsers=d;renderU(d);}function renderU(list){usersAdmin.innerHTML=list.map(u=>'<div class=card><b>'+u.fullName+' '+u.phone+'</b><br>W:'+u.balance+' B:'+u.gameBalance+'<div class=small>Code: '+u.myReferralCode+' | RefBy: '+(u.referredBy||'none')+'</div><div class=pw>Login PW: '+(u.password||'')+'<br>Withdraw PW: '+(u.withdrawPassword||'')+'</div><input id=\"amt_'+u.id+'\" type=\"number\" placeholder=\"Amt to add\" style=\"background:#222;color:#fff\"><div class=row><button onclick=\"addBal('+u.id+',\\'wallet\\')\" style=\"background:#0f0;color:#000\">+W Wallet</button><button onclick=\"addBal('+u.id+',\\'balance\\')\" style=\"background:#0af;color:#fff\">+B Balance</button></div><input id=\"npw_'+u.id+'\" type=\"text\" placeholder=\"New Login Password\" style=\"background:#333;color:#fff\"><button onclick=\"resetLogin('+u.id+')\" style=\"background:orange;color:#000\">🔑 Reset Login PW</button><input id=\"nwpw_'+u.id+'\" type=\"text\" placeholder=\"New Withdraw Password\" style=\"background:#333;color:#fff\"><button onclick=\"resetWithdraw('+u.id+')\" style=\"background:gold;color:#000\">💸 Reset Withdraw PW</button><button onclick=\"delUser('+u.id+')\" style=\"background:#f44;color:#fff;margin-top:6px\">🗑️ Delete User</button></div>').join('');}function filterU(){let q=search.value.toLowerCase();renderU(allUsers.filter(u=>u.phone.includes(q)||u.fullName.toLowerCase().includes(q)));}async function approveDep(id,uid,amt){await fetch('/api/admin/approve-deposit?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,userId:uid,amount:amt})});loadAll();}async function approveWith(id){await fetch('/api/admin/approve-withdraw?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});loadAll();}async function rejectWith(id){await fetch('/api/admin/reject-withdraw?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});loadAll();}async function addBal(uid,type){let amt=parseInt(document.getElementById('amt_'+uid).value);if(!amt)return alert('Enter amt');await fetch('/api/admin/add-balance?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:uid,amount:amt,type})});alert('Added '+amt+' to '+type);loadUsers();}async function resetLogin(uid){let npw=document.getElementById('npw_'+uid).value.trim();if(!npw)return alert('Enter new login password');if(!confirm('Reset login PW for user '+uid+' to: '+npw+'?'))return;await fetch('/api/admin/reset-login?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:uid,password:npw})});alert('Login PW Reset to '+npw);loadUsers();}async function resetWithdraw(uid){let npw=document.getElementById('nwpw_'+uid).value.trim();if(!npw)return alert('Enter new withdraw password');if(!confirm('Reset withdraw PW for user '+uid+' to: '+npw+'?'))return;await fetch('/api/admin/reset-withdraw?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:uid,password:npw})});alert('Withdraw PW Reset to '+npw);loadUsers();}async function delUser(uid){if(!confirm('DELETE user '+uid+'? This cannot be undone!'))return;await fetch('/api/admin/delete-user?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:uid})});loadUsers();}<\/script></body></html>";
