app.post('/api/virtual/bet/acca',async(req,res)=>{try{if(virtualPhase!=='betting')return res.status(400).json({error:"BETTING CLOSED"});const{userId,amount,selections}=req.body;if(amount<500||amount>5000)return res.status(400).json({error:"Bet 500 - 5000 only"});const users=await db.query("SELECT balance,gameBalance FROM users WHERE id=?",[userId]);let u=users[0][0];let tot=(u.balance||0)+(u.gameBalance||0);if(tot<amount)return res.status(400).json({error:"No balance"});let useG=Math.min(u.gameBalance||0,amount);if(useG>0)await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[useG,userId]);if(amount-useG>0)await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount-useG,userId]);let md=matchday+1;const oddsMap={home:1.5,away:1.8,draw:1.9};let rawOdd=1;selections.forEach(s=>{rawOdd*=(oddsMap[s.prediction]||1.5);});let finalOdd=parseFloat((rawOdd*0.90).toFixed(2));await db.query("INSERT INTO virtual_accas (userId,season,matchday,selections,amount,odd) VALUES (?,?,?,?,?,?)",[userId,season,md,JSON.stringify(selections),amount,finalOdd]);res.json({ok:1,md,odd:finalOdd});}catch(e){res.status(400).json({error:e.message});}});
app.get('/api/games/crash/status',(req,res)=>res.json(crashState));
let crashBetsMap=new Map();
app.post('/api/games/crash/bet',async(req,res)=>{try{if(crashState.phase!=='betting')return res.status(400).json({error:"Betting closed"});const{userId,amount}=req.body;if(crashBetsMap.has(userId))return res.status(400).json({error:"Already bet"});const users=await db.query("SELECT balance,gameBalance FROM users WHERE id=?",[userId]);let u=users[0][0];let tot=(u.balance||0)+(u.gameBalance||0);if(tot<amount)return res.status(400).json({error:"No balance"});let useG=Math.min(u.gameBalance||0,amount);if(useG>0)await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[useG,userId]);if(amount-useG>0)await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount-useG,userId]);crashBetsMap.set(userId,{amount,cashed:false});res.json({ok:1});}catch(e){res.status(400).json({error:e.message});}});
app.post('/api/games/crash/cashout',async(req,res)=>{try{const{userId}=req.body;if(crashState.phase!=='flying')return res.status(400).json({error:"Not flying"});let bet=crashBetsMap.get(userId);if(!bet||bet.cashed)return res.status(400).json({error:"No bet"});bet.cashed=true;let win=Math.floor(bet.amount*crashState.mult);await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[win,userId]);await db.query("INSERT INTO crash_bets (userId,amount,cashoutAt,crashAt,status,win) VALUES (?,?,?,?,?,?)",[userId,bet.amount,crashState.mult,crashState.crashPoint,'won',win]);crashBetsMap.delete(userId);res.json({ok:1,win,mult:crashState.mult});}catch(e){res.status(400).json({error:e.message});}});
setInterval(async()=>{if(crashState.phase==='crashed'){for(let entry of crashBetsMap.entries()){let uid=entry[0],bet=entry[1];if(!bet.cashed){try{await db.query("INSERT INTO crash_bets (userId,amount,crashAt,status,win) VALUES (?,?,?,'lost',0)",[uid,bet.amount,crashState.crashPoint]);}catch(e){}}}crashBetsMap.clear();}},1000);
app.post('/api/games/wheel/spin',async(req,res)=>{try{const{userId,amount}=req.body;const users=await db.query("SELECT balance,gameBalance FROM users WHERE id=?",[userId]);let u=users[0][0];let tot=(u.balance||0)+(u.gameBalance||0);if(tot<amount)return res.status(400).json({error:"No balance - Add funds"});let useG=Math.min(u.gameBalance||0,amount);if(useG>0)await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[useG,userId]);if(amount-useG>0)await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount-useG,userId]);const mults=[0,1.5,2.0,2.5,3.0],weights=[0.35,0.25,0.20,0.12,0.08];let r=Math.random(),acc=0,chosen=0;for(let i=0;i<mults.length;i++){acc+=weights[i];if(r<=acc){chosen=mults[i];break;}}let win=Math.floor(amount*chosen);if(win>0)await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[win,userId]);await db.query("INSERT INTO wheel_bets (userId,amount,mult,win,status) VALUES (?,?,?,?,?)",[userId,amount,chosen,win,chosen>0?'won':'lost']);res.json({mult:chosen,win});}catch(e){res.status(400).json({error:e.message});}});
app.post('/api/games/dice/roll',async(req,res)=>{try{const{userId,amount,target,type}=req.body;const users=await db.query("SELECT balance,gameBalance FROM users WHERE id=?",[userId]);let u=users[0][0];let tot=(u.balance||0)+(u.gameBalance||0);if(tot<amount)return res.status(400).json({error:"No balance"});let useG=Math.min(u.gameBalance||0,amount);if(useG>0)await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[useG,userId]);if(amount-useG>0)await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount-useG,userId]);let roll=Math.floor(Math.random()*100)+1,winCond=type==='over'?roll>target:roll<target,prob=type==='over'?(100-target)/100:target/100,mult=prob>0?(0.97/prob):1,win=winCond?Math.floor(amount*mult):0;if(win>0)await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[win,userId]);await db.query("INSERT INTO dice_bets (userId,amount,roll,target,type,win,status) VALUES (?,?,?,?,?,?,?)",[userId,amount,roll,target,type,win,winCond?'won':'lost']);res.json({roll,win,mult:mult.toFixed(2)});}catch(e){res.status(400).json({error:e.message});}});
app.get('/api/user/:id',async(req,res)=>{try{const r=await db.query("SELECT * FROM users WHERE id=?",[req.params.id]);res.json(r[0][0]||{balance:0,gameBalance:0});}catch(e){res.json({balance:0,gameBalance:0});}});
app.get('/api/withdrawals/:id',async(req,res)=>{try{const r=await db.query("SELECT * FROM withdrawals WHERE userId=? ORDER BY id DESC",[req.params.id]);res.json(r[0]);}catch(e){res.json([]);}});
app.get('/api/investments/:id',async(req,res)=>{try{const r=await db.query("SELECT * FROM investments WHERE userId=? ORDER BY id DESC",[req.params.id]);res.json(r[0]);}catch(e){res.json([]);}});
app.post('/api/register',async(req,res)=>{try{let code='LIFE'+Math.random().toString(36).slice(2,5).toUpperCase()+Math.floor(Math.random()*9),ref=req.body.referredBy||'';await db.query("INSERT INTO users (fullName,phone,password,withdrawPassword,myReferralCode,referredBy,balance,gameBalance) VALUES (?,?,?,?,?,?,0,0)",[req.body.name,req.body.phone,req.body.password,req.body.withdrawPassword,code,ref]);let r=await db.query("SELECT * FROM users WHERE phone=? ORDER BY id DESC LIMIT 1",[req.body.phone]);res.json(r[0][0]);}catch(e){res.status(400).json({error:e.message});}});
app.post('/api/login',async(req,res)=>{try{let r=await db.query("SELECT * FROM users WHERE phone=? AND password=?",[req.body.phone,req.body.password]);if(r[0].length)res.json(r[0][0]);else res.status(401).json({error:"Wrong"});}catch(e){res.status(401).json({error:"Wrong"});}});
app.post('/api/deposit',async(req,res)=>{try{const{userId,amount,airtelNo,screenshot,screenshotHash}=req.body;let u=await db.query("SELECT phone FROM users WHERE id=?",[userId]);await db.query("INSERT INTO deposits (userId,phone,amount,airtelNo,screenshot,screenshotHash) VALUES (?,?,?,?,?,?)",[userId,u[0][0].phone,amount,airtelNo,screenshot,screenshotHash]);res.json({ok:1});}catch(e){res.status(400).json({error:e.message});}});
app.post('/api/invest',async(req,res)=>{try{const{userId,club,amount}=req.body;let u=await db.query("SELECT balance FROM users WHERE id=?",[userId]);if(!u[0][0]||u[0][0].balance<amount)return res.status(400).json({error:"No WALLET - Add WALLET in Admin"});await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount,userId]);await db.query("INSERT INTO investments (userId,club,amount,rate,lockDays) VALUES (?,?,?,?,?)",[userId,club,amount,10,10]);res.json({ok:1});}catch(e){res.status(400).json({error:e.message});}});
app.post('/api/withdraw',async(req,res)=>{try{const{userId,amount,phone,withdrawPassword}=req.body;let u=await db.query("SELECT gameBalance,withdrawPassword FROM users WHERE id=?",[userId]);if(u[0][0].withdrawPassword!==withdrawPassword)return res.status(400).json({error:"Wrong withdraw password"});if(u[0][0].gameBalance<amount)return res.status(400).json({error:"No BALANCE"});await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[amount,userId]);await db.query("INSERT INTO withdrawals (userId,phone,amount) VALUES (?,?,?)",[userId,phone,amount]);res.json({ok:1});}catch(e){res.status(400).json({error:e.message});}});
app.get('/api/history/:id',async(req,res)=>{try{let d=await db.query("SELECT amount,status,'deposit' as type FROM deposits WHERE userId=?",[req.params.id]);let a=await db.query("SELECT amount,status,'acca' as type FROM virtual_accas WHERE userId=?",[req.params.id]);res.json([...d[0],...a[0]]);}catch(e){res.json([]);}});
app.get('/api/team/:id',async(req,res)=>{try{let u=await db.query("SELECT myReferralCode FROM users WHERE id=?",[req.params.id]);let t=await db.query("SELECT phone,fullName FROM users WHERE referredBy=?",[u[0][0].myReferralCode]);res.json({team:t[0]});}catch(e){res.json({team:[]});}});
